const fs = require('fs');
const { D, body, h1, h2, center, pageBreak, caption, note, table, makeDoc } = require('./lib');
const figure = (file, w, h, alt, text) => [new D.Paragraph({ alignment: D.AlignmentType.CENTER, keepNext: true, spacing: { before: 120, after: 60 }, children: [new D.ImageRun({ type: 'png', data: fs.readFileSync(__dirname + '/fig/' + file), transformation: { width: w, height: h }, altText: { title: alt, description: alt, name: alt } })] }), new D.Paragraph({ spacing: { line: 240, before: 0, after: 240 }, children: require('./lib').runs(text, { size: 20 }) })];

const TITLE = 'When Do LLM Operators Skip Verification? Goal Visibility, Reasoning, and Framing in an Automated Maintenance Environment';
const ABSTRACT = 'Organizations increasingly consider delegating maintenance decisions to large language model (LLM) operators, and the prompt that describes the situation is the only contract between principal and operator. We ask which features of that interface govern whether an operator skips verification, in an environment where skipping is dominated and every outcome is scored by rule. We first test the registered loss-chasing hypothesis, that a loss description of a failed update raises skipping, and find no support in three models (Study 1). Five further studies then examine what is associated with skipping, each writing every frame in 16 independently generated wordings, so that wording is the unit of replication. In a fast commercial model (Claude Haiku 4.5), skipping appears under time pressure (27.2% of first choices with three turns left, 0.5% with six, and none with twelve). Stating the target in the headline raised it by up to 54 percentage points, whereas loss text lowered it by 13. Extended thinking lowered it to 9.7%, and stating each option\'s expected quality change lowered it without removing it. Three larger commercial models (Sonnet 5.5, Opus 5.5, and Fable 5.1) did not skip in any of 4,320 first choices each, so the question is not informative for them. A screen of seven small models from other vendors, fixed before the runs, found one more model that skips (Gemini 2.5 Flash-Lite), with the same ordering of frames and an effect of target visibility; the other valid models skipped little or not at all. The pattern is consistent with goal visibility and reasoning, not loss accounting, as the interface features that matter. We contribute a design that treats wording as the unit of replication, a measurement argument for excess risk over an expected-value benchmark, and guidance for stating objectives, setting reasoning budgets, and auditing operator models.';
const KEYWORDS = 'large language models; delegation to AI; interface design; AI maintenance; framing; prospect theory; goal visibility; reasoning models; AI governance; behavioral evaluation';

const c = [];
const P = (t, o) => c.push(body(t, o));
const NI = { noIndent: true };

c.push(body('', NI));
c.push(center(TITLE, { bold: true }));
c.push(center('Manuscript submitted to *Information Systems Research* (double-anonymous review version)'));
c.push(center('**Abstract**', { keepNext: true }));
c.push(body(ABSTRACT, NI));
c.push(body('**Keywords:** ' + KEYWORDS, NI));
c.push(pageBreak());

// ---------------- 1 Introduction
c.push(h1('1. Introduction'));
P('The quality of a deployed large language model (LLM) is not fixed at launch. Knowledge goes stale, live traffic drifts away from the data on which reward models were trained, prompts and guardrails accumulate edits, and offline evaluation sets diverge from what users ask. Maintenance is therefore a repeated decision under uncertainty that collapses to a small set of options: hold, apply a narrow or wide patch, apply either without running the regression tests, or roll back. Each option trades expected quality gain against the risk of a further incident and against the turns, and hence the time, that verification consumes.');
P('Some of these decisions are increasingly proposed for delegation to LLM-based agents that operate the maintenance pipeline themselves. Whether such an operator behaves like the disciplined engineer a runbook presupposes is an empirical question with consequences for information systems governance. Behavioral research gives reasons for doubt. Prospect theory holds that people are risk seeking below a reference point and risk averse above it (Kahneman and Tversky 1979) and that the same outcome coded as a gain or a loss changes the choice (Tversky and Kahneman 1981); in gambling this appears as loss chasing, in which a decision maker places further bets, even of negative expected value, to get back to break-even (Thaler and Johnson 1990). If an LLM operator inherits such tendencies, a dashboard line such as "the last update cost us two points" could make it more willing to skip verification when verification matters most.');
P('Prior work asks whether LLMs show human-like biases in classic economic tasks (Horton 2023; Ross et al. 2024; Bini et al. 2026) and whether gambling-like risk taking appears in generated output (Du 2025). It rarely asks the operational question: in a repeated loop, after a failed update, does the model choose a larger change and omit verification, and is that choice moved by the accounting frame alone? Answering it requires an environment in which the correct choice is known, so that a departure can be attributed to loss accounting and not to a reasonable response to time pressure, and a design that does not mistake a property of one sentence for a property of a frame.');
P('The question also has an information systems reading. Delegating maintenance to an AI operator creates an agency relationship in which the principal cannot observe whether the agent verified its work (Jensen and Meckling 1976; Eisenhardt 1989), and the status text the operator reads is a control signal through which the principal directs it (Kellogg et al. 2020). Which signals induce which shortcuts is open for delegation to AI (Raisch and Krakowski 2021), and it matters because skipped verification leaves hidden technical debt (Sculley et al. 2015).');
P('We place an LLM in the role of an on-call lead and manipulate the headline sentence (loss, gain-to-goal, or neutral, all carrying identical facts), the failures injected into the history and, in later studies, the turns left, the model, its reasoning setting, and whether the target is stated. Every test-skipping option has a strictly lower expected value than its verified counterpart, everything is scored by rule, and no human participants are recruited. The registered hypothesis is one candidate explanation among several, so we treat the paper as a study of which features of the delegation interface govern skipping: the valence of the status text, the visibility of the target, the turns left, reasoning, the information shown about the options, and the model tier (Section 2.6).');
P('The paper reports six studies in sequence. Study 1 executes the registered protocol on three small models and does not support the loss-chasing hypothesis. It left three questions open: whether the frame effect survives when each frame is written in many independent wordings, what determines skipping in the one model that skips, and whether models that did not skip differ in kind or are held back by something that can be varied. Studies 2 to 4 address them, Study 5 asks whether skipping persists when the dominance of verification is made visible, and Study 6, governed by a screening rule fixed before the runs, asks whether small models from other vendors show the same pattern. Studies 2 to 6 were designed after Study 1 and are not part of the registered protocol; we say so where each is reported and do not adjust any interval for that fact.');
P('We make four contributions. First, we move the question from whether LLMs copy human biases to which features of the delegation interface control an operator\'s risk behavior: in the fast commercial model that skips, and in part in a small model from a second vendor, the visibility of the target and the time left are associated with large differences in skipping and reasoning with a large reduction, whereas the loss or gain wording of the headline is not a driver of it. Second, we report a registered test of loss chasing, defined through three jointly necessary conditions in an environment where skipping is dominated, and then identify what is associated with skipping instead; the registered hypothesis is not supported. Third, we provide a design in which wording is the unit of replication, with 16 independently generated wordings per frame so that frame, wording, and interaction effects can be separated, and a measurement argument: when a rollback of positive expected value exists, the natural test that risk rises after failures mislabels rational retreat, so we propose excess risk over an expected-value benchmark together with test-skipping. Fourth, we show where the question is informative: three larger commercial models that reason by default did not skip, so frame effects cannot be estimated for them. We also provide a human-subject-free audit that an organization can run on a candidate operator before delegating maintenance decisions to it.');
P('Section 2 develops the theory, the hypotheses, and the propositions that organize the studies, Section 3 gives an overview of the studies, and Section 4 describes the environment and procedure. Sections 5 to 10 report the six studies. Section 11 discusses contributions, implications, and limitations.');

// ---------------- 2 Theory
c.push(h1('2. Theoretical Background and Hypotheses'));
c.push(h2('2.1 Reference dependence, framing, and loss chasing'));
P('Prospect theory replaces the expected-utility assumption that only final wealth matters with a value function defined over gains and losses relative to a reference point: concave for gains, convex for losses, and steeper for losses than for gains (Kahneman and Tversky 1979). Two consequences are relevant here. A decision maker whose outcome sits below the reference point should favor the high-variance option, and a change in how the same numbers are described should change which option is chosen, even though an expected-utility maximizer should ignore the description (Tversky and Kahneman 1981). Thaler and Johnson (1990) show that prior outcomes shift risk taking in sequences of gambles, with prior losses producing risk seeking when a chance to break even is offered. The analogue in maintenance is a failed update that leaves quality below the last stable level: a wide or unverified patch offers a chance to recover the loss at once.');
P('In maintenance the reference point is either the last stable quality or an explicit target. The same score of 102 can be described as "+2 against a baseline of 100," as "-2 from a previous 104," or as "+6 remaining to a target of 108." An expected-utility operator should ignore the sentence. A prospect-theoretic operator should raise the share of high-variance actions, namely wide patches and skipped tests, under the loss description.');
c.push(h2('2.2 LLMs as decision makers'));
P('A growing literature treats LLMs as simulated economic agents (Horton 2023) and evaluates them with utility-theoretic tasks. Ross et al. (2024) conclude that current models are neither *homo economicus* nor faithful replicas of human participants, with weaker loss aversion than in human samples, steeper time discounting, and inconsistency when the framing of a task changes. Bini et al. (2026) study corrections of such biases, and Du (2025) documents gambling-like risk taking in generation tasks. Payne (2025) reports choices consistent with prospect theory in reasoning models, with framing effects that vary by scenario, and Wang and Zhang (2026) find that logically equivalent framings shift choices across model families. These studies mostly examine one-shot allocation or risk choices. A separate line of work places agents under pressure in simulated work settings: a GPT-4 trading agent acted on an insider tip and concealed its reasons more often under pressure (Scheurer et al. 2023), agents have been reported to trade safety for utility, with stronger reasoning accelerating the decline (Jiang and Tang 2026), coding agents violate their instructions more often under sustained pressure (Saebo et al. 2026), and long-horizon agents are biased toward submitting an answer that looks complete as the end approaches (Chen et al. 2026). A study of reasoning effort found that two tiers of a commercial model avoided a forbidden tool at both low and maximum settings (Xu and Wu 2026). Our environment differs in that the correct choice is known from the payoff structure, the shortcut is a dominated option and not a rule violation, and the manipulation separates the valence of the status text from the visibility of the goal. Because alignment training (Ouyang et al. 2022) may make behavior differ across models even with identical prompts, we test more than one model.');
c.push(h2('2.3 Maintenance as a repeated risky choice'));
P('Operational guidance recommends a fixed regression set, recurring audits, and dated knowledge entries. These are normative checklists. They do not tell us whether a decision maker who is already in a loss frame will bypass them. A rival account is also plausible: status quo bias (Samuelson and Zeckhauser 1988) predicts that after a failure an operator will hold or roll back rather than gamble. The design must therefore be able to distinguish loss chasing from conservatism.');
c.push(h2('2.4 Definition and registered hypotheses'));
P('We define loss chasing as a policy that jointly satisfies three conditions. (1) The last outcome is a failure, or unrealized cumulative loss is positive. (2) The chosen action is a high-risk option that is inferior in expected value, namely skipping the tests. (3) That action is significantly more frequent than under a gain or neutral frame in the same state. Condition (2) is essential: if skipping were not inferior in expected value, a rise in skipping could be read as a rational response to a time budget. Four hypotheses were pre-specified.');
P('**H1 (framed loss chasing).** Holding quality, remaining turns, and failure history fixed, the loss frame raises the test-skip rate relative to the gain-to-goal frame.', NI);
P('**H2 (escalation after consecutive failures).** Risk taking increases as the number of injected consecutive failures moves from zero to one to three.', NI);
P('**H3 (framing separated from facts).** Behavior splits when the state vector is identical and only the headline sentence changes, so that the effect is one of accounting and not of information.', NI);
P('**H4 (delayed recovery brake).** After a small success, the skip rate does not return immediately to baseline if unrealized cumulative loss remains.', NI);
P('The rival prediction was recorded in advance: if status quo bias dominates, holding and rollback increase under the loss frame, and the design yields a negative result, namely that gambling-like patterns observed in generation do not reproduce in an operational role.');
c.push(h2('2.5 Goal visibility and reasoning: hypotheses stated after Study 1'));
P('Goals act as reference points (Heath et al. 1999), and effort and speed change as a goal gets close (Kivetz et al. 2006). Goal setting raises effort and performance (Locke and Latham 2002), and the same specificity that motivates can also induce shortcut taking and rule bending when a target is hard to reach (Schweitzer et al. 2004; Ordóñez et al. 2009). In agency terms, a target in a status line is a goal communicated by the principal to an agent whose verification effort it cannot observe. A target stated in a status line therefore offers a second route to the high-variance action that does not run through loss: with few turns left and a visible gap to close, skipping verification is a way to reach the target in time. This route predicts that stating the target raises skipping whatever the valence of the sentence, and it differs from loss chasing, which predicts that loss text raises skipping with the target held fixed. We also expect that a model that deliberates before answering is less likely to accept an inferior option it can reason about. Three hypotheses follow, stated after Study 1 and tested in Studies 2 to 4.');
P('**H5 (goal visibility).** Stating the target in the headline raises the test-skip rate, whether the sentence is written as a loss or as neutral status.', NI);
P('**H6 (valence).** Holding the target statement fixed, loss text does not raise the test-skip rate relative to neutral text; if anything it lowers it. This is the direction the rival account in Section 2.4 allows and loss chasing excludes.', NI);
P('**H7 (reasoning).** Enabling extended reasoning lowers the test-skip rate, and larger commercial tiers that reason by default skip no more often than the fast tier with reasoning enabled.', NI);

c.push(h2('2.6 Conceptual model and propositions'));
P('The hypotheses above come from two sources: the registered account (H1 to H4) and the goal and reasoning accounts stated after Study 1 (H5 to H7). Together they describe one conceptual model. Verification skipping by an LLM operator is a function of features of the delegation interface (the valence of the status text, whether the target is visible in it, the turns left, whether the operator reasons before acting, and the information shown about the options), conditional on the model tier. The prompt is the principal\'s only channel to the operator, so each feature is a configuration choice that the principal controls. Box 1 states the propositions and where they are tested.');
c.push(caption('**Box 1.** Propositions, hypotheses, and studies.'));
c.push(table(['Proposition', 'Statement', 'Hypothesis', 'Study'], [
  ['P1 Goal visibility', 'Skipping is higher when the target is stated in the decision context.', 'H5', '4'],
  ['P2 Reasoning', 'Reasoning before acting lowers skipping.', 'H7', '3, 2'],
  ['P3 Time pressure', 'Skipping appears when few turns remain.', 'Design factor of Study 2', '2'],
  ['P4 Framing', 'Loss text does not raise skipping relative to gain or neutral text; if anything it lowers it.', 'H1, H6', '1, 2, 4'],
  ['P5 Information', 'Showing the expected quality change of each option lowers skipping but does not remove it.', 'Stated after Study 4', '5'],
  ['P6 Tier', 'Larger commercial tiers that reason by default skip no more often than the fast tier with reasoning.', 'H7', '2'],
], [1700, 4660, 1700, 1300]));
c.push(note('*Note.* P1 to P6 summarize the pattern of the evidence; H1 to H4 were registered, and H5 to H7 and P3 to P6 were stated after Study 1.'));

// ---------------- 3 Overview
c.push(h1('3. Overview of the Studies'));
c.push(caption('**Table 1.** Studies, questions, and designs.'));
c.push(table(['Study', 'Question', 'Models', 'Design', 'First choices'], [
  ['1 (registered)', 'Does the loss frame raise skipping? Does failure history?', 'Qwen2.5-1.5B, SmolLM2-1.7B, Claude Haiku 4.5', '3 frames x 3 failure levels, 12 turns left, one headline per frame (the registered wording)', '100 per cell'],
  ['2', 'Is the frame effect robust to wording and to time pressure? Does it differ by model?', 'Haiku 4.5, Sonnet 5.5, Opus 5.5, Fable 5.1, plus the two open models at 3 and 12 turns', '3 frames x 16 independently generated wordings x 3 time conditions (12, 6, 3 turns left), 0 failures', '30 per cell; 4,320 per model'],
  ['3', 'Does reasoning remove skipping?', 'Haiku 4.5 with extended thinking', '3 frames x 16 wordings, 3 turns left', '30 per cell; 1,440'],
  ['5', 'Does skipping persist when the expected quality change of each option is stated?', 'Haiku 4.5', 'Study 4 design (5 frames x 16 wordings, target in the facts line) with the expected quality change appended to every option, 3 turns left', '30 per cell; 2,400'],
  ['6', 'Do small models from other vendors show the same pattern?', 'Seven small models from five vendors (through one aggregator)', 'Screen at 3 turns left (3 frames x 16 wordings x 30); the model that passes is also run at 12 and 6 turns and in the Study 4 design', '1,440 per model screened; 2,880 and 4,800 more for the model that passes'],
  ['4', 'Is the effect of goal visibility separate from loss accounting?', 'Haiku 4.5', '5 frames (valence x target in headline) x 16 wordings, facts line with and without the target, 3 turns left', '30 per cell; 2,400 per run'],
], [1300, 2300, 2000, 2700, 1060]));
c.push(note('*Note.* A first choice is the turn immediately after history injection; a cell is one frame by wording by condition combination.'));

// ---------------- 4 Method
c.push(h1('4. Environment and Procedure'));
c.push(h2('4.1 Environment'));
P('An episode has a turn budget of 12, a starting quality of 100, a target of 108, and a rollback baseline of 100. Each turn the operator chooses one of six actions. Table 2 gives the hidden payoff structure. The operator is told only a qualitative description of each option (for example, "large fix, skip regression tests; large gain, very high risk of a severe incident, costs one turn"), not the probabilities or payoffs.');
c.push(caption('**Table 2.** Hidden payoff structure and expected values (quality points).'));
c.push(table(['Action', 'Gain if success', 'P(fail)', 'Change if fail', 'Turn cost', 'Risk index', 'Expected value'], [
  ['hold', '0', '0.00', '0', '1', '0.00', '0.00'],
  ['narrow_patch', '+1', '0.25', '-1', '2', '0.40', '+0.50'],
  ['narrow_skip', '+1', '0.45', '-2', '1', '0.80', '-0.35'],
  ['wide_patch', '+3', '0.40', '-3', '3', '0.60', '+0.60'],
  ['wide_skip', '+3', '0.65', '-5', '1', '1.00', '-2.20'],
  ['rollback', 'quality to 100', '0.00', 'loss realized', '1', '0.20', '100 - quality'],
], [1500, 1300, 1000, 1400, 1100, 1100, 1960]));
c.push(note('*Note.* The expected value of the last row depends on the state: after *n* injected failures quality is 100 - 2*n*, so rollback is worth +2*n* points. Expected values for the skip options are below their verified counterparts, so skipping is dominated.'));
P('Rollback restores quality to the baseline, books any unrealized loss as realized, and resets the failure streak. The other actions resolve by a hidden Bernoulli trial. Unrealized loss is max(0, 100 - quality). The episode ends when cumulative turn cost reaches 12; early stopping at the target is off, because it would distort comparisons of the remaining budget across conditions. Random draws are pre-generated from the episode seed so that every model faces the same world.');
c.push(h2('4.2 History injection, time pressure, and frames'));
P('Consecutive failures are injected into the history before the first free choice and are not forced during play. After *n* injected failures, quality is set to 100 - 2*n*, the last action to narrow_skip, and the last outcome to fail. Time pressure is set by the number of turns already spent when the first choice is made: zero (12 turns left), six (6 left), or nine (3 left). All frames present the same fact vector (quality, target, remaining turns, last action and outcome, failure streak, deviation from baseline, and gap to target); only the headline sentence differs. *Loss frame:* "The last result reduced quality by *d* points. Unrealized cumulative loss is *L*." *Gain-to-goal frame:* "*g* points remain to the target. Current quality *q* / 108." *Neutral frame:* "Current quality *q*. Last result: fail." The order of the action list is rotated by turn index to remove position effects. Study 4 adds two frames (Section 8) and a variant of the fact vector without the target. The exact prompts are in Online Appendix B.');
c.push(h2('4.3 Models and procedure'));
P('The system role is a fixed on-call lead whose objective is to maximize terminal quality and who is told that a single -5 incident is severe. Output must be JSON with an action and a one-line reason. Parse failures are mapped to hold and flagged. Study 1 used two small open models executed locally on CPU (Qwen2.5-1.5B-Instruct and SmolLM2-1.7B-Instruct) at temperature 0.7 and Claude Haiku 4.5 through its programming interface at temperatures 0.0 and 0.7. For the open models the opening characters of the JSON response were pre-filled in the assistant turn, because a 0.5-billion-parameter pilot replied with a bare action name and every response failed to parse; this forces the output format and could itself influence the choice. Study 2 used four commercial models: Haiku 4.5 (temperature 0.7), Sonnet 5.5, Opus 5.5, and Fable 5.1, which was run at three turns left only to limit cost; Studies 3, 4, and 5 used Haiku 4.5. The Sonnet, Opus, and Fable tiers accept no temperature argument and are run at the model default; the runs record this per row. Study 3 enabled extended thinking in Haiku 4.5 with a budget of 2,000 tokens, which also precludes setting a temperature.');
c.push(h2('4.4 Independently generated wordings'));
P('A single sentence per frame confounds the frame with the sentence, and a first choice depends only on the prompt and on sampling, so the episodes in a cell are repeated draws on one wording. To estimate frame effects we generated 16 wordings per frame (the registered headline plus 15 paraphrases) with a language model that was given only the facts and the placeholders, and not the research question or any result. The generator was asked for Claude Sonnet 5.5; the provider returned the batches for the loss and neutral frames from a fallback model (named claude-sonnet-5 in the response) after the requested model declined them, and the batch for the gain frame from the requested model. Candidates were accepted by mechanical rules (the required placeholders only, no digits, no vocabulary belonging to a different frame, length limits, no duplicates), and the first 15 valid candidates in the order generated were kept; none was rejected. The wordings were frozen and hashed before any Study 2 to 4 run (content hash 4d25f0374b8f) and are listed in Online Appendix E. Index 0 of each frame is the registered headline.');
c.push(h2('4.5 Outcomes and analysis'));
P('The primary sample is the first free choice in each episode, because later turns are path dependent. The primary outcome is an indicator for skipping tests (narrow_skip or wide_skip). In Study 1 we estimate a logistic model with frame, injected-failure category, and their interaction, and adjust the two pre-specified contrasts (loss versus gain-to-goal; three failures versus zero) with the Holm procedure, separately for each model. H1 is counted as supported if the loss frame exceeds the gain-to-goal frame by at least ten percentage points and remains significant after adjustment. As benchmarks we use the expected-value-maximizing policy, always choosing narrow_patch, and always holding. We also compute a risk index (Table 2) and an excess risk, defined as the risk index of the chosen action minus that of the expected-value-maximizing action in the same state.');
P('In Studies 2 to 4 the wording is the unit of replication. For each model and condition we compute the skip rate in every frame-by-wording cell, take contrasts between frames within each wording, and average them over wordings. Intervals are 95% percentile intervals from a bootstrap that resamples wordings (4,000 resamples), so that they reflect wording-to-wording variation and not only episode noise. We also report how many wordings put the loss frame above and below the gain-to-goal frame, the standard deviation of the loss-minus-gain contrast across wordings and the part of it that exceeds binomial sampling noise, and the shares of the total squared deviation of the wording-by-frame table of skip rates that are due to frame, wording, and their interaction, with the expected contribution of sampling noise as a floor. When a model does not skip in any cell, the contrasts are not estimable and the cell is reported as a floor, not as a null. The analysis scripts for Studies 2 to 6 were committed to the repository before the corresponding runs. We report no *p* values for these studies; the contrasts are descriptive, with intervals over wordings.');

// ---------------- 5 Study 1
c.push(h1('5. Study 1: Registered Protocol'));
c.push(h2('5.1 Scope'));
P('Study 1 is a partial execution of the registered grid: three models from three developers, each a small model of its family. For the commercial family only the small, fast tier was run, so the registered size contrast is not tested. Open models were run at temperature 0.7 only. Later turns were not analyzed, so H4 and the chase-streak, rollback-latency, and terminal-quality outcomes are not reported. H3 is addressed by the design: the fact vector is identical across frames. One earlier attempt with the commercial model was discarded because every call failed with a client error that was silently retried, producing rows consisting only of the default hold; it is excluded from all results. Parse failure was 0.0% for the Qwen and Claude runs and 0.7% for SmolLM2.');
c.push(h2('5.2 H1: loss frame versus gain-to-goal frame'));
c.push(caption('**Table 3.** Study 1 first-choice test-skip rate by model, injected failures, and frame (100 episodes per cell).'));
c.push(table(['Model', 'Failures', 'Gain-to-goal', 'Loss', 'Neutral'], [
  ['Qwen2.5-1.5B', '0', '17%', '31%', '21%'],
  ['', '1', '14%', '15%', '14%'],
  ['', '3', '8%', '16%', '15%'],
  ['SmolLM2-1.7B', '0', '5%', '0%', '3%'],
  ['', '1', '17%', '13%', '14%'],
  ['', '3', '14%', '8%', '13%'],
  ['Claude Haiku 4.5', 'all', '0%', '0%', '0%'],
], [2600, 1400, 1800, 1800, 1760]));
c.push(note('*Note.* Claude Haiku 4.5 pooled over both temperatures (200 episodes per cell), twelve turns left. Open models at temperature 0.7.'));
P('Pooled over failure levels, the loss-minus-gain difference is +7.7 percentage points for Qwen (Holm-adjusted *p* = .012), -5.0 points for SmolLM2 (Holm *p* = .036), and exactly zero for Claude. H1 is not supported for any model. Qwen\'s difference has the predicted sign but is below the registered ten-point threshold. SmolLM2\'s difference has the opposite sign. For Claude the test is uninformative: nobody skips in any condition at twelve turns left, so there is no variation to compare. Qwen\'s excess is concentrated where there is no failure history (31% with zero injected failures, where the headline reads "unrealized cumulative loss is 0"); the frame-by-failures interaction is not significant for either open model (Qwen *p* = .56; SmolLM2 *p* = .26).');
c.push(h2('5.3 H2: behavior after consecutive failures'));
P('After a failure, rollback has a positive expected value (+2*n* points after *n* injected failures), so the expected-value-maximizing policy lowers its risk index, from 0.60 with no history to 0.20 after three failures. The registered H2 test therefore classifies the rational benchmark as a non-instance, and an operator that simply fails to retreat looks riskier than it is. Table 4 reports the registered rule and a criterion, specified after Study 1 output, that requires excess risk to rise by at least 0.10 (Welch *p* < .05) and skipping to rise.');
c.push(caption('**Table 4.** Behavior after three injected failures relative to none.'));
c.push(table(['Model', 'Risk index', 'Registered H2', 'Excess risk', 'Skip rate', 'Excess-risk criterion'], [
  ['Qwen2.5-1.5B', '0.635 to 0.568', 'not met', '+0.035 to +0.368', '23.0% to 13.0%', 'not met'],
  ['SmolLM2-1.7B', '0.127 to 0.184', 'met', '-0.473 to -0.016', '2.7% to 11.7%', 'met'],
  ['Claude Haiku 4.5', '0.534 to 0.200', 'not met', '-0.066 to 0.000', '0% to 0%', 'not testable'],
], [1700, 1700, 1300, 1800, 1500, 1360]));
P('Qwen does not retreat to rollback after failures (its excess risk rises) but it skips less (logit coefficient for three versus zero failures -0.70, Holm *p* = .003): it under-responds to failure and does not chase. SmolLM2 skips more after failures (2.7% to 11.7%; coefficient +1.58, Holm *p* < .001) in all three frames, a failure-history effect independent of framing; its excess risk after three failures is about zero, so it is not riskier than a rational agent. Claude behaves like the benchmark and retreats after failures. An early version of the automatic analysis flagged Claude\'s H2 as supported only because all three-failure values were identical, so that their variance was zero; that was an artifact.');
P('Study 1 leaves two results open. The commercial model never skipped with twelve turns left, so the frame could not be tested in it; and every frame appears as one sentence, so the small open-model differences cannot be separated from the sentences that carry them. Studies 2 to 4 take these up.');

// ---------------- 6 Study 2
c.push(h1('6. Study 2: Wording, Time Pressure, and Model Tier'));
P('Study 2 asks whether the frame effect survives when each frame is written in 16 independent wordings, whether it appears when turns are scarce, and how it differs across commercial tiers. Each cell has 30 first choices at temperature 0.7 for Haiku 4.5 and at the model default for Sonnet 5.5, Opus 5.5, and Fable 5.1, with no injected failures, at 12, 6, and 3 turns left: 3 frames x 16 wordings x 30 episodes = 1,440 first choices per condition and 4,320 per model.');
c.push(caption('**Table 5.** Study 2: skip rate and frame contrasts over 16 wordings, by model and turns left.'));
c.push(table(['Model', 'Turns left', 'Skip rate (min-max over cells)', 'Loss minus gain, pp [95% CI over wordings]', 'Neutral minus gain, pp [95% CI]', 'SD across wordings (excess over noise), pp', 'Loss above / below gain', 'Variation: frame / wording / interaction (noise floor)'], [
  ['Haiku 4.5', '12', '0%', 'not estimable (floor)', 'not estimable', '-', '-', '-'],
  ['', '6', '0.5% (0.0%-13.3%)', '-1.5 [-3.5, 0.0]', '-1.5 [-3.5, 0.0]', '3.6 (3.0)', '0 / 3', '10.2% / 29.9% / 59.9% (29.6%)'],
  ['', '3', '27.2% (0.0%-100%)', '-62.9 [-82.5, -41.9]', '-50.4 [-74.2, -22.9]', '42.0 (41.6)', '0 / 15', '52.4% / 9.7% / 37.9% (1.3%)'],
  ['Sonnet 5.5', '12, 6, 3', '0% in every cell', 'not estimable (floor)', 'not estimable', '-', '-', '-'],
  ['Opus 5.5', '12, 6, 3', '0% in every cell', 'not estimable (floor)', 'not estimable', '-', '-', '-'],
  ['Fable 5.1', '12, 6, 3', '0% in every cell', 'not estimable (floor)', 'not estimable', '-', '-', '-'],
], [1100, 700, 1300, 1400, 1200, 1100, 900, 1660]));
c.push(note('*Note.* 16 wordings x 30 episodes per cell. Intervals resample wordings. Variation shares are shares of the total squared deviation of the wording-by-frame table of skip rates; the interaction share and the noise floor both include sampling noise.'));
c.push(...figure('fig1.png', 595, 346, 'Skip rate by turns left and model', '**Figure 1.** Test-skip rate by turns left at the first choice and model (all frames and wordings pooled; 1,440 first choices per point). The larger tiers lie on the zero line; The thinking condition was run at three turns left only.'));
P('Haiku 4.5 did not skip with twelve turns left, almost never with six (0.5%), and skipped in 27.2% of first choices with three left, with cell rates from 0% to 100%. At three turns left the loss frame was below the gain-to-goal frame in 15 of 16 wordings and above it in none, by 62.9 percentage points on average, and the neutral frame was below it by 50.4 points. Frame explained 52.4% of the variation in the wording-by-frame table, wording 9.7%, and the interaction 37.9%, against a noise floor of 1.3%, so the interaction share is real: wordings differ in how strongly they separate the frames. The ordering of the gain and neutral frames is not stable across wordings. Loss-frame cells never exceeded 16.7%, gain-frame cells ranged from 6.7% to 100%, and neutral-frame cells from 0% to 83.3%; under the registered wording the neutral frame skipped in 83.3% of first choices and the gain frame in 6.7%, the reverse of the average ordering. The robust contrast is that loss text yielded little skipping under every wording, whereas gain and neutral text yielded anything from little to nearly universal skipping depending on the wording. The direction of loss minus gain is opposite to H1.');
P('The loss wordings differ in how emotive their verb is (\"knocked down,\" \"took a hit,\" \"eroded\" versus \"reduced,\" \"dropped,\" \"decreased\"), which could by itself lower skipping. We grouped the 16 loss wordings by verb from the wording text alone, before inspecting any wording-level result: six with emotive verbs (knocked down, slipped, degraded, took a hit, eroded, worsened) and ten with plain verbs. At three turns left the loss frame was below the gain frame by 55.6 points [-87.8, -20.0] across the emotive wordings (5 of 6 below) and by 67.3 points [-89.0, -42.7] across the plain wordings (10 of 10 below); the difference between the groups was +11.8 points [-29.4, +54.3]. Loss-frame skip rates were 3.9% for emotive and 1.0% for plain wordings (difference +2.9 points [-1.3, +8.4]). The negative loss-minus-gain contrast is therefore present among the plain-verb wordings alone, and emotive verbs do not lower loss-frame skipping in these data, although the interval for the group difference is wide.');
P('Study 2 involves several contrasts. As a check on multiplicity we recomputed the three-turn intervals at the 99.6% level, which corresponds to a Bonferroni adjustment over 12 contrasts: loss minus gain was -62.9 points [-89.2, -33.8] and neutral minus gain -50.4 points [-82.5, -9.0], both still excluding zero.');
P('Sonnet 5.5 and Opus 5.5 did not choose a skip action in any of 4,320 first choices each, and Fable 5.1 did not in any of its 4,320 first choices. The floor is not an artifact of failed calls: parse failure was at most 0.09%, no model refused, and the actions chosen were narrow_patch in at least 97% of first choices, with wide_patch in at most 2.8% (more often with fewer turns left) and hold in at most 1.3%, both verified or non-risky options. Fable 5.1 also showed no parse failure and no refusal in any condition, and chose narrow_patch in 99.7%, 97.4%, and 96.0% of first choices at 12, 6, and 3 turns left, with wide_patch in the remainder. Because the contrast cannot be estimated, these models neither support nor contradict a frame effect; this environment elicited no skipping from them under any of the 48 sentences (including Fable 5.1).');
P('The two open models of Study 1 were not rerun with the 16 wordings. A pilot with the registered headlines only (three turns left against twelve, zero and three injected failures, 50 episodes per cell at three turns) showed no turn-scarcity effect in them (overall skip rate 18.0% at twelve turns and 18.3% at three for Qwen, 7.2% versus 7.7% for SmolLM2; frame-by-scarcity interaction not significant, *p* = .88 and .38), and their frame differences kept their signs. The turn-scarcity effect therefore appears specific to the commercial model that skips, although the pilot is small.');
P('The result changes how Study 1 should be read. In the model that skips, what looked like a null at twelve turns left (0% everywhere) was a floor, and the effect appears only under time pressure; its direction is opposite to the registered one. It also indicates that the loss frame is not the frame associated with skipping. Study 4 asks what is.');

// ---------------- 7 Study 3
c.push(h1('7. Study 3: Does Reasoning Remove Skipping?'));
P('Sonnet 5.5 and Opus 5.5 reason before answering and Haiku 4.5 in Study 2 did not. To separate reasoning from tier we ran Haiku 4.5 again at three turns left with extended thinking enabled (a budget of 2,000 tokens), with the same 16 wordings and 30 episodes per cell. Enabling thinking precludes a temperature setting, so sampling is at the model default; this is a second difference from Study 2.');
c.push(caption('**Table 6.** Study 3: Haiku 4.5 at three turns left, without and with extended thinking.'));
c.push(table(['Condition', 'Skip rate (min-max over cells)', 'Loss minus gain, pp [95% CI]', 'Neutral minus gain, pp [95% CI]', 'Loss above / below gain'], [
  ['No thinking (Study 2)', '27.2% (0.0%-100%)', '-62.9 [-82.5, -41.9]', '-50.4 [-74.2, -22.9]', '0 / 15'],
  ['Extended thinking', '9.7% (0.0%-23.3%)', '-5.2 [-9.6, -1.0]', '-6.2 [-9.8, -2.7]', '4 / 10'],
], [2100, 2100, 1900, 1900, 1360]));
P('Thinking reduced the overall skip rate from 27.2% to 9.7% and the largest cell rate from 100% to 23.3%. The frame gaps shrank by an order of magnitude (loss minus gain from -62.9 to -5.2 points), and their direction, with the gain-to-goal frame highest, was preserved. Variation in the wording-by-frame table was mostly interaction and noise (frame 21.6%, wording 26.5%, interaction 51.9%, noise floor 76.0%), so with thinking the cell rates are small and unstable and individual wordings differ from each other more than the frames do. Reasoning therefore appears to account for most, but not all, of the difference between the fast tier and the larger tiers: with thinking enabled the fast tier still skips in about 10% of first choices, whereas Sonnet 5.5, Opus 5.5, and Fable 5.1 do not skip at all. Either a residual tier effect or the difference in the amount of reasoning could explain the remainder; the design does not separate them.');

// ---------------- 8 Study 4
c.push(h1('8. Study 4: Goal Visibility and Valence'));
P('The frames of Studies 1 to 3 differ in two ways at once: their valence (loss, gain, or neutral) and whether the target and the gap to it appear in the headline. The gain-to-goal headline names the target; the loss and neutral headlines do not. Study 4 crosses the two. We added two frames. *Neutral-goal* places the neutral headline together with the target headline of the same wording index (valence-free, target stated), and *loss-goal* places the loss headline together with that target headline (loss, target stated). With the existing neutral, loss, and gain frames this gives five frames. Study 4 also varied whether the facts line below the headline shows the target and the gap to it. Each run has 5 frames x 16 wordings x 30 episodes = 2,400 first choices at three turns left in Haiku 4.5 at temperature 0.7.');
c.push(caption('**Table 7.** Study 4: skip rate by frame (mean over 16 wordings, Haiku 4.5, three turns left).'));
c.push(table(['Facts line', 'Neutral', 'Loss', 'Gain', 'Neutral + target', 'Loss + target'], [
  ['With the target', '15.0%', '1.9%', '62.3%', '69.2%', '32.1%'],
  ['Without the target', '0.0%', '0.0%', '56.0%', '31.7%', '23.8%'],
], [2300, 1400, 1400, 1400, 1500, 1360]));
c.push(caption('**Table 8.** Study 4: contrasts in percentage points, with 95% intervals over wordings and the number of wordings in each direction (positive / negative).'));
c.push(table(['Contrast', 'Facts line with target', 'Facts line without target'], [
  ['Goal effect, neutral text (neutral + target minus neutral)', '+54.2 [+36.0, +70.2]; 13 / 2', '+31.7 [+14.4, +50.8]; 12 / 0'],
  ['Goal effect, loss text (loss + target minus loss)', '+30.2 [+13.8, +48.5]; 13 / 2', '+23.8 [+6.0, +46.2]; 4 / 0'],
  ['Valence without target (loss minus neutral)', '-13.1 [-23.8, -4.4]; 2 / 11', '0.0 [0.0, 0.0]; 0 / 0'],
  ['Valence with target (loss + target minus neutral + target)', '-37.1 [-56.5, -15.6]; 3 / 12', '-7.9 [-29.0, +12.9]; 3 / 9'],
  ['Interaction (valence with target minus without)', '-24.0 [-44.6, -4.2]; 5 / 11', '-7.9 [-29.0, +12.9]; 3 / 9'],
  ['Registered contrast (loss minus gain)', '-60.4 [-80.8, -38.8]; 2 / 14', '-56.0 [-73.8, -38.7]; 0 / 15'],
  ['Gain minus neutral + target (both state the target)', '-6.9 [-27.3, +12.7]; 8 / 7', '+24.4 [+6.5, +41.9]; 12 / 4'],
], [4000, 2680, 2680]));
c.push(...figure('fig2.png', 595, 384, 'Skip rate by frame in Study 4', '**Figure 2.** Study 4: test-skip rate by frame (mean over 16 wordings; Haiku 4.5, three turns left, 480 first choices per bar). Gain, neutral + target, and loss + target state the target in the headline.'));
P('Stating the target raised skipping substantially whatever the valence (H5): by 54.2 points with neutral text and by 30.2 points with loss text when the facts line also shows the target, and by 31.7 and 23.8 points when it does not. The effect is positive in 13 of 16 wordings and negative in 2 (neutral text, target also in the facts line). Loss text did not raise skipping (H6); it lowered it, by 13.1 points without a target statement and by 37.1 points with one, and the registered contrast came out at -60.4 points. With the target removed from the facts line, neutral and loss text produced no skipping at all (0.0%), so when the target is visible nowhere in the prompt, skipping disappears in these two frames.');
P('Two further results qualify the reading. When both frames state the target in the facts line, the gain frame and the neutral-plus-target frame are not distinguishable (-6.9 points, interval -27.3 to +12.7), so the gain-to-goal effect of the earlier studies appears to be an effect of stating the target and not of a gain wording. When the target appears only in the headline, the gain frame skipped more than neutral-plus-target (+24.4 points, 95% interval +6.5 to +41.9), but the 99.6% interval includes zero (-1.0 to +49.2), so we do not treat this difference as established. The neutral-plus-target frame adds a status sentence to the target headline, and the added sentence may reduce skipping, but the data do not identify why.');
P('As in Study 2, we recomputed the Study 4 intervals at the 99.6% level. With the target in the facts line, the goal effect with neutral text (+54.2 points [+27.5, +75.8]), the goal effect with loss text (+30.2 [+8.5, +57.5]), valence without a target statement (-13.1 [-28.8, -1.5]), valence with one (-37.1 [-64.0, -5.8]), and the registered contrast (-60.4 [-87.7, -29.6]) all stay clear of zero; the interaction (-24.0 [-52.3, +4.4]) and the gain minus neutral-plus-target check (-6.9 [-36.2, +21.0]) do not. Without the target in the facts line, the goal effect with neutral text (+31.7 [+7.9, +59.6]) and the registered contrast (-56.0 [-81.3, -30.6]) stay clear of zero, the goal effect with loss text just reaches it (+23.8 [0.0, +55.6]), and the remaining contrasts include zero. The main reading, that stating the target raises skipping and loss text does not, therefore rests on contrasts that survive the stricter level; the interaction and the finer comparisons among target-stating frames do not, and we do not rely on them.');
P('Together with Study 3, the pattern is that, in this model, a visible gap to the target and few turns left go with skipping verification, loss text goes with more caution, and reasoning goes with most of the skipping disappearing. This pattern is more consistent with a goal-directed shortcut than with loss chasing. A loss-chasing operator would be expected to skip more under the loss text with the target held fixed, and this model does not.');

// ---------------- 9 Study 5
c.push(h1('9. Study 5: Is Skipping Still Chosen When Its Dominance Is Visible?'));
P('In Studies 1 to 4 the operator sees only qualitative option descriptions, so the dominance of verification is visible to the designer but not to the operator. Skipping could then be a defensible trade-off from the operator\'s information, in which case it would not satisfy condition (2) of our definition. Study 5 makes the dominance visible. Every option description ends with its expected quality change, computed from the payoff table: hold +0.00, narrow_patch +0.50, narrow_skip -0.35, wide_patch +0.60, wide_skip -2.20, and for rollback the change to the baseline (+0.00 at quality 100). The design is that of Study 4 with the target in the facts line: 5 frames x 16 wordings x 30 episodes = 2,400 first choices in Haiku 4.5 at temperature 0.7, with three turns left and no injected failures. The comparison is with the Study 4 run of the same design without expected values, paired by wording. The comparison script was committed before the run, and Study 5 is not registered.');
c.push(caption('**Table 9.** Study 5: skip rate by frame without and with the expected quality change stated (mean over 16 wordings; Haiku 4.5, three turns left).'));
c.push(table(['', 'Neutral', 'Loss', 'Gain', 'Neutral + target', 'Loss + target'], [
  ['Expected values not shown (Study 4)', '15.0%', '1.9%', '62.3%', '69.2%', '32.1%'],
  ['Expected values shown (Study 5)', '10.2%', '0.0%', '25.0%', '17.3%', '21.5%'],
  ['Change, pp [95% CI over wordings]', '-4.8 [-17.1, +5.6]', '-1.9 [-3.8, -0.4]', '-37.3 [-61.0, -10.8]', '-51.9 [-65.2, -38.1]', '-10.6 [-32.5, +12.1]'],
], [2500, 1300, 1300, 1500, 1400, 1360]));
c.push(note('*Note.* Intervals resample wordings; the two runs share the design but not the sampling draws.'));
P('Showing the expected values (Table 9) lowered skipping most where it had been highest: by 37.3 points in the gain frame and by 51.9 points in the neutral-plus-target frame, with smaller changes elsewhere. Skipping did not disappear. With the negative expected quality change of skipping stated, 25.0% of first choices in the gain frame, 21.5% in the loss-plus-target frame, and 17.3% in the neutral-plus-target frame were skip actions. The contrasts in Studies 2 to 4 kept their direction in this run. Within the expected-value run, stating the target raised skipping with loss text by 21.5 points [8.5, 36.5] (10 of 16 wordings positive, none negative) and with neutral text by 7.1 points [-7.1, +22.9] (8 positive, 6 negative); loss text lowered skipping relative to neutral text by 10.2 points [-17.9, -3.8] (8 wordings negative, none positive, the rest equal); and the registered contrast (loss minus gain) was -25.0 points [-43.3, -9.6].');
P('Two readings follow. Part of the skipping in Studies 2 to 4 reflects an operator that does not know the expected value of its options, as the large reductions show. A remainder is chosen when the dominance is visible, in the frames that state the target, which is the combination that condition (2) of the definition of loss chasing requires, although loss text still does not raise it. Three cautions apply. The added text lengthens every option and could act as a cue about what the designer expects. The two runs share a design but not their sampling draws. And a skip action still saves one turn against two or three for a verified action, so the choice remains consistent with a trade of expected quality for speed that the operator judges worthwhile when time is short; the design does not tell us whether the model weighs a chance of reaching the target.');

// ---------------- 10 Study 6
c.push(h1('10. Study 6: Replication in Small Models from Other Vendors'));
P('The main results of Studies 2 to 5 come from one model that skips. Study 6 asks whether small models from other vendors show the same pattern. Before any run we fixed a screening rule in a plan that was committed to the repository: seven small models, reached through one aggregator, were each run at three turns left in the Study 2 design (3 frames x 16 wordings x 30 episodes, 1,440 first choices, temperature 0.7 where the model accepts it). A model passes the screen if at least 5% of its first choices skip verification, so that frame contrasts can be estimated. A run in which more than 5% of first choices are parse failures or refusals is invalid and is not read as a floor. Models that pass are also run at 12 and 6 turns left and in the Study 4 design with and without the target in the facts line. Every candidate that was run is reported.');
c.push(caption('**Table 10.** Study 6: screening of seven small models at three turns left (1,440 first choices each).'));
c.push(table(['Model', 'Skip rate', 'Loss', 'Gain', 'Neutral', 'Parse failures', 'Screen'], [['Gemini 2.5 Flash-Lite', '17.2%', '4.4%', '30.6%', '16.7%', '3', 'Passes'], ['Ministral-8B', '4.0%', '0.6%', '11.5%', '0.0%', '0', 'Below 5%'], ['Llama-3.1-8B', '2.4%', '2.9%', '2.5%', '1.7%', '0', 'Below 5%'], ['Gemini 3.1 Flash-Lite', '0.0%', '0.0%', '0.0%', '0.0%', '0', 'Floor'], ['Gemma-3-12B', '0.0%', '0.0%', '0.0%', '0.0%', '0', 'Floor'], ['GPT-5-nano', 'not valid', '', '', '', '1,440', 'Excluded (invalid run)'], ['Qwen3-14B', 'not valid', '', '', '', '1,276', 'Excluded (invalid run)']], [2300, 1000, 900, 900, 1000, 1500, 1760]));
c.push(note('*Note.* Skip rates are pooled over frames and wordings; the loss, gain, and neutral columns are the rates in each frame. The plan with the screening rule is dated before the runs.'));
P('Of the seven models, one passed the screen. Gemini 2.5 Flash-Lite skipped in 17.2% of first choices at three turns left, with the same ordering of frames as Haiku 4.5 (gain 30.6%, neutral 16.7%, loss 4.4%). Its loss frame skipped less than its gain-to-goal frame (-26.2 points, 95% interval -41.5 to -12.9 over wordings; below in 11 of 16 wordings and above in 1), and its neutral frame skipped less than its gain frame (-14.0 [-27.1, -1.7]). Ministral-8B did not meet the 5% rule (4.0%), but its ordering was the same (loss 0.6%, neutral 0.0%, gain 11.5%; loss minus gain -10.8 [-24.0, -1.7]); we report it as below the screen and did not extend it. Llama-3.1-8B (2.4%) showed no frame difference (+0.4 [-1.0, +1.9]), and Gemini 3.1 Flash-Lite and Gemma-3-12B did not skip in any cell, so the question is not informative for them. The first runs of GPT-5-nano and Qwen3-14B, which reason by default, returned empty answers in 1,440 and 1,276 first choices because the output budget of 200 tokens was used by hidden reasoning; these runs are invalid and are not interpreted as floors; we did not repeat them, and the two models are excluded from the comparison. For the models with valid runs there were at most three parse failures and no refusals in 1,440 first choices.');
P('Gemini 2.5 Flash-Lite skipped under time pressure only (0.3%, 1.5%, and 17.2% of first choices at twelve, six, and three turns left). In the Study 4 design, stating the target in the headline raised skipping when the target was not in the facts line (+6.9 points [+0.2, +18.1] with neutral wording and +6.0 [+1.5, +12.7] with loss wording), loss text did not raise it (loss minus neutral +0.0 [-0.6, +0.6] without a target statement and -15.4 [-29.4, -4.0] with one), and the registered contrast was negative in both runs (-29.2 [-44.2, -14.6] and -20.8 [-35.4, -8.3]). Online Appendix F gives the tables and the full results.');
P('Two cautions apply. The intervals are 95% intervals over wordings and are not adjusted for multiplicity, as in Studies 2 to 5. And one of seven models passing the screen is a modest base for generalization: the pattern is present in two small models from two vendors, with a smaller frame difference in the second (-26.2 against -62.9 points at three turns left), and it is absent or too small to estimate in the others. We therefore do not claim that it holds for small models in general.');


// ---------------- 11 Discussion
c.push(h1('11. Discussion'));
c.push(h2('11.1 Summary of findings'));
P('The registered question is whether an LLM maintenance operator chases losses because of accounting frames. We find no evidence of it in the three models of Study 1, in the four commercial tiers of Study 2, or in the fast tier with thinking or with the target manipulated in Studies 3 and 4 (P4). Where skipping occurs, it is associated with time pressure (P3) and with a visible target (P1), reasoning removes most of it (P2), stating the expected quality change of each option lowers it without removing it (P5), and larger commercial tiers that reason by default did not skip at all (P6). A small model from a second vendor (Gemini 2.5 Flash-Lite) showed the same ordering of frames, the effect of time pressure, and an effect of target visibility, while the other four valid small models skipped little or not at all (Study 6). The finding is not that framing is irrelevant: the headline sentence moved the fast tier\'s skipping from 0% to 100% across conditions. It is that the ingredient that mattered appears to be what the sentence tells the operator about the goal, and not whether it describes a loss.');
c.push(h2('11.2 Theoretical contributions'));
P('The contributions follow the conceptual model in Section 2.6. First, the paper moves the question from whether an LLM reproduces a human bias to which features of the delegation interface control its risk behavior; the features that mattered here, the visibility of the target, reasoning, and time pressure, are all set by the principal. Second, a registered test of a prominent behavioral claim is reported as specified, and later studies identify what is associated with the behavior instead, so that a null result comes with an account of what moves it. Third, the design in which wording is the unit of replication, with variance shares for frame, wording, and interaction, is a procedure that other studies of LLMs as subjects can use. Fourth, the floor effects in three larger models mark the boundary within which the question is informative.');
P('We contribute to the behavioral literature on LLMs by separating two accounts that prior framing studies often leave confounded. Loss chasing predicts that loss text raises risk taking with everything else held fixed. Goal visibility predicts that stating the target raises it whatever the valence. The 2 x 2 design in Study 4 separates them, and the data are closer to the second. Goals act as reference points (Heath et al. 1999) and effort shifts as a goal draws near (Kivetz et al. 2006); our results are consistent with an operator that, given a visible gap and few turns, trades verification for speed, and they show that this does not require, and is not helped by, a description of loss. A prospect-theoretic reading remains possible if loss text refers to a past reference (the last stable level) and goal text to a future one; the data say that the second reference, not the first, moves the choice. We do not claim to identify a mechanism inside the model.');
P('For information systems research, the results bear on how control signals work in AI delegation. Research on algorithmic control emphasizes what systems monitor and direct (Kellogg et al. 2020), and research on automation emphasizes human reliance on machines (Raisch and Krakowski 2021). Our data add a third element: the text through which a principal communicates goals to an AI agent is itself a lever on the agent\'s verification behavior. The pattern that a specific, visible target is associated with shortcut taking in the fast model parallels the human findings on goal setting (Schweitzer et al. 2004; Ordóñez et al. 2009), and it suggests that insights from agency and goal-setting theory may transfer to AI agents, with the caveat that a language model has no motives and that we identify no mechanism.');
P('Our reasoning result sits beside work reporting the opposite pattern. Jiang and Tang (2026) find that stronger reasoning makes agents more likely to trade safety for utility under pressure, whereas we find less skipping with reasoning in the fast model and none in the larger tiers. The two need not conflict. Their setting makes compliance infeasible and sets a rule against a goal, whereas in ours the verified options remain feasible and the shortcut is a dominated option, so deliberation can favor the verified route. We cannot tell which feature of the settings accounts for the difference, and a design that varies both within one environment would be needed to say.');
P('We also contribute a measurement argument. In environments where a recovery option has positive expected value after a loss, the intuitive escalation test, "does the risk index rise after failures?", is confounded by the normative benchmark: the rational operator lowers it, so the test rewards the wrong behavior in both directions. We recommend that evaluations of this kind (i) compute the expected-value-maximizing action in every state and report excess risk over it, (ii) require the inferior high-risk action, here test-skipping, to rise before calling a pattern loss chasing, (iii) check that the dominance of the inferior action is visible to the operator or learnable by it, since a verbal description of the options can turn a dominated action into a defensible time-risk trade-off when turns are scarce, (iv) estimate any frame effect over many independently generated wordings, treating the wording as the unit of replication, (v) report a floor effect explicitly as a non-test and not as a null, and (vi) vary the target statement and the valence separately, because a "gain" frame that names the goal bundles two manipulations.');
c.push(h2('11.3 Implications for information systems practice'));
P('For organizations that consider delegating maintenance decisions to an LLM, the implication is an audit, not a rule about wording. How an operator model responds to a status line depends on the model, on whether it reasons, on how close the target is, and on the sentence. Four practices follow. First, audit the candidate model on the organization\'s own payoff structure with many wordings of each message and with its reasoning setting fixed as it will be deployed; the same model skipped verification in 27% of cases with its default setting and in 10% with thinking enabled. Second, treat status text, including how prominently a target or a gap to it is shown, as controlled configuration: it moved the fast model\'s skipping by tens of points, and it should be versioned and re-tested when it changes. Third, loss-worded messages should not be assumed to be the risk; in this environment they were associated with the least skipping in the fast model, and the wording associated with the most skipping displayed a target. Fourth, for unattended operation under deadlines, a reasoning-enabled tier and a deployment gate that makes verification the default are worth considering: the cost is low and the gate removes the option that the environment defines as dominated.');
c.push(h2('11.4 Limitations'));
P('First, the commercial ladder confounds tier with reasoning and sampling control: Sonnet 5.5, Opus 5.5, and Fable 5.1 accept no temperature argument and reason by default, and Study 3 suggests that reasoning accounts for much of the difference to Haiku 4.5; we do not claim a size effect. Second, the main results come from two small models that skip, from two vendors, in one condition (no injected failures) at three turns left; Study 1 covers failure history only at twelve turns left. Third, Studies 2 to 6 were designed after Study 1 and were not registered. Their analysis scripts were written before the runs and their contrasts are descriptive, but the questions they answer were shaped by earlier output, the studies together make many comparisons, and the intervals are not adjusted for multiplicity, although the three-turn contrasts of Study 2 and the main contrasts of Study 4 stay clear of zero at the 99.6% level while the interaction and several finer contrasts do not. Fourth, the 16 wordings per frame were generated by a language model and filtered by mechanical rules, with two of three batches served by a fallback model; they are not a random sample of all possible wordings, and loss wordings contain stronger affect verbs than the gain and neutral wordings, which could contribute to the lower skipping under loss text, although a split of loss wordings by verb in Study 2 does not support this (a comparison of six and ten wordings with a wide interval). Fifth, the format pre-fill for the open models is an intervention outside the registered protocol, and the open models were run at temperature 0.7 only. We also started the 16-wording design on the two open models and stopped it for reasons of time, with 966 of 1,440 first choices for one model and none for the other, without analyzing the partial output; the open models therefore appear only in Study 1 and in the Study 2 pilot. In Study 6, two of seven small models produced invalid runs and are excluded, and only one model passed the screen. Sixth, a scalar quality score compresses multidimensional incidents into one line, and the six closed actions simplify the continuous space of field work. Seventh, a model does not feel loss; it reacts to text statistics, the design does not identify the mechanism by which a sentence changes a choice, and the reasons the models give are post hoc and are not used as evidence. Eighth, in Studies 1 to 4 the operator sees only qualitative option descriptions, so part of the skipping may be a defensible trade-off from its information; Study 5 shows that skipping persists at 17% to 25% in the target-stating frames when the expected quality change is stated, but also lowers it substantially, and the added text may act as a cue. Ninth, results depend on the model version at the time of the run, and external validity is left to follow-up work applying the same coding scheme to live tickets.');
c.push(h2('11.5 Conclusion'));
P('We asked which features of the delegation interface govern an LLM operator\'s decision to skip verification, starting from the registered test of whether the accounting frame of a failed update moves it toward skipping, using an environment in which skipping is dominated and all outcomes are scored by rule. The registered protocol did not support loss chasing. Six studies, five of them with independently generated wordings and registered analysis scripts, suggest that, in the fast commercial model that skips, the shortcut is associated with a visible target under time pressure, is lower under loss text, and is largely absent with reasoning, that a small model from a second vendor showed the same ordering of frames and an effect of target visibility, and that three larger commercial models did not skip. A deployed operator should therefore be treated as a decision maker whose sensitivity to the status line, to the visibility of its goal, and to its own reasoning setting is an empirical property of that model, to be measured before delegation and again when the messages it reads change.');

// ---------------- Declarations
c.push(h1('Data, Code, and Ethics'));
P('No human participants were recruited, so the study involves no human-subjects research; the terms of use of each model provider were followed. The prompts, state machine, seeds, parser, wording generator, wording file, runner, and analysis scripts, together with the raw logs of all runs, are available for review in an anonymized replication package; the link is withheld for double-anonymous review. Deviations from the registered protocol and the order in which the studies were designed are listed in Section 4 and in Online Appendix D.');

